package com.termbridge.android.brain.personalization

import org.junit.Assert.*
import org.junit.Test

class PersonalControlTest {
    private val features = listOf(0.9, 0.5, 0.8, 0.0, 1.0, 1.0)
    private val row = ControlFeedback("a", "g", 1, features, "addressed", 1)
    @Test fun feedbackIsImmediateButSeparateFromASRAndReversible() {
        val model = ControlModel.train(listOf(row), "v1")
        // Generated by the TS trainer; this guards wire parameter order and update parity.
        val golden = listOf(0.3905160088653645, 0.3514644079788279, 0.19525800443268224,
            0.3124128070922915, 0.0, 0.3905160088653645, 0.3905160088653645)
        golden.forEachIndexed { i, weight -> assertEquals(weight, model.addressed[i], 1e-12) }
        assertTrue(model.probability("addressed", features) > 0.5)
        assertEquals(0.5, model.probability("finished", features), 0.000001)
        assertEquals(model, ControlModel.train(listOf(row, row), "v1"))
        assertEquals(ControlModel(), ControlModel.train(emptyList(), "base-v1"))
        assertTrue(ControlModel.train(listOf(row.copy(label = 0)), "v2").probability("addressed", features) < 0.5)
    }
    @Test fun observationPipeRetainsOnlyBoundedScalarsAndClearsAtBoundary() {
        val observation = ControlObservation()
        repeat(50) { observation.frame(0.9f, it * 32L) }
        val x = observation.snapshot(3000, false, true, true)!!
        assertEquals(0.32, x[1], 0.000001)
        assertTrue(x.all { it in 0.0..1.0 })
        assertNull(observation.snapshot(4000, false, true, true))
        observation.frame(Float.NaN, 5000)
        assertNull(observation.snapshot(6000, false, false, false))
    }
    @Test(expected = IllegalArgumentException::class) fun invalidModelCannotReplaceHead() {
        ControlModel(addressed = listOf(Double.NaN))
    }
    @Test fun receiptsRejectFractionalAndUnsafeNumbersInsteadOfTruncating() {
        val wire = mapOf("schema" to 1L, "mode" to "shadow", "version" to "v1", "samples" to 1L,
            "addressed" to List(7) { 0.0 }, "finished" to List(7) { 0.0 })
        assertEquals(1, ControlModel.fromWire(wire).samples)
        assertEquals(1234L, ControlModel.wireRevision(1234L))
        for (value in listOf(1.5, Double.NaN, Long.MAX_VALUE, 9_007_199_254_740_992L, 0L)) {
            assertTrue(runCatching { ControlModel.wireRevision(value) }.isFailure)
        }
        assertTrue(runCatching { ControlModel.fromWire(wire + ("schema" to 1.5)) }.isFailure)
        assertTrue(runCatching { ControlModel.fromWire(wire + ("samples" to 1.5)) }.isFailure)
        assertTrue(runCatching { ControlModel.fromWire(wire + ("mode" to "active")) }.isFailure)
    }
}
